		qd := snap.QueueDepth + snap.PendingRequests
		if qd < minQD {
			minQD = qd
		}
	}

	inputLen := len(req.InputTokens)
	isSession := req.SessionID != ""

	for _, snap := range snapshots {
		qd := snap.QueueDepth + snap.PendingRequests

		// Stronger quadratic queue-depth penalty (0.45 vs 0.35)
		qdDiff := float64(qd - minQD)
		if qdDiff > 0 {
			scores[snap.ID] *= 1.0 / (1.0 + 0.45*qdDiff*qdDiff)
		}

		// Tiered input-length-aware cache bonus (slightly stronger for large)
		if inputLen > 256 {
			scores[snap.ID] += 0.48 * snap.CacheHitRate
		} else if inputLen > 64 {
			scores[snap.ID] += 0.30 * snap.CacheHitRate
		} else {
			scores[snap.ID] += 0.15 * snap.CacheHitRate
		}

		// Session affinity bonus
		if isSession {
			scores[snap.ID] += 0.40 * snap.CacheHitRate
		}

		// KV memory pressure: continuous penalty above 0.70 threshold
		if snap.KVUtilization > 0.9 {
			scores[snap.ID] *= 0.12
		} else if snap.KVUtilization > 0.70 {
			// Smooth scaling: goes from 1.0 at 0.70 to ~0.45 at 0.90
			pressure := (snap.KVUtilization - 0.70) / 0.20
